import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with the given {@code name}.
     * The method protects against directory‑traversal attacks by normalising the
     * resolved path and ensuring it stays within {@code dir}.  If a file with the
     * same name already exists, a numeric suffix is appended until a free name
     * is found.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain sub‑directories)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code name} would resolve outside {@code dir}
     * @throws NullPointerException     if {@code dir} or {@code name} is {@code null}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new NullPointerException("Directory and name must not be null");
        }

        // Strip query parameters that may appear in URLs or ZIP entry names
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the base directory and normalise it
        Path dirPath   = dir.toPath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still under the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempt to create a file outside the allowed directory: " + name);
        }

        File file = targetPath.toFile();

        // Determine prefix and suffix for generating a unique file name
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            targetPath = dirPath.resolve(newName).normalize();
            file = targetPath.toFile();
        }

        // Create any missing parent directories
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods
}
```

