public class URIBuilder {

    // other methods

    /**
     * Normalizes a URI path by ensuring it starts with a single leading slash
     * and removing any excess leading slashes.  The method also handles
     * {@code null} and empty strings gracefully.
     *
     * @param path the original path component
     * @return a normalized path that always begins with '/' unless the
     *         original path was empty; {@code null} if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Fast‑path for an empty string – keep it unchanged.
        if (path.isEmpty()) {
            return "";
        }

        // Count leading slashes.
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // If the entire string was slashes, collapse to a single '/'.
        if (i == path.length()) {
            return "/";
        }

        // Remove all leading slashes.
        String trimmed = path.substring(i);

        // Prepend a single leading slash to the remaining path.
        return '/' + trimmed;
    }

    // other methods

}
