    /* --------------------------------------------------------------------- */

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}. The method validates
     * the string representation against a whitelist of acceptable locale
     * formats before constructing the {@link Locale} to prevent malicious
     * input from being processed.
     *
     * @param requestedLocale the parameter from the request
     * @return the validated {@link Locale}, or {@code null} if the input is
     *         invalid or {@code null}
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;

        if (requestedLocale == null) {
            return null;
        }

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            // Validate against the whitelist pattern
            if (VALID_LOCALE_PATTERN.matcher(localeStr).matches()) {
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
            } else {
                LOG.warn("Attempted to create Locale from invalid format: '{}'", localeStr);
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

