    // Defensive check: size must be non‑negative for STORED entries.
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }

    // If we've already read the declared amount, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // Underlying stream ended before we reached the expected size.
            // Signal EOF to the caller.
            return -1;
        }
        if (l == 0) {
            // Avoid a potential infinite loop if the stream returns 0 bytes.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // Corruption check: we must not have read more bytes than the entry declares.
        if (current.bytesReadFromStream > csize) {
            throw new IOException("Corrupted ZIP entry: read more bytes (" +
                    current.bytesReadFromStream + ") than declared (" + csize + ")");
        }
