import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the incoming request is allowed to modify the SCIM user.
     *
     * <p>Security enhancements:</p>
     * <ul>
     *   <li>Ensures the authenticated user matches the user ID in the request path.</li>
     *   <li>Uses {@link Objects#equals(Object,Object)} for null‑safe comparisons.</li>
     *   <li>Rejects updates that attempt to change the primary email unless the
     *       authenticated user is the same as the target user.</li>
     * </ul>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is permitted, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Verify that the caller is authenticated and is the owner of the account.
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            // No authenticated principal – deny access
            return false;
        }

        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        if (!Objects.equals(authenticatedUserId, id)) {
            // The authenticated user is attempting to modify someone else's account
            return false;
        }

        // 2. Load the current user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere)
            return true;
        }

        // 3. Parse the request body into a ScimUser object
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // 4. Perform field‑by‑field comparison using null‑safe equality
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(),
                            scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(),
                            scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(),
                            scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the request is allowed
        return true;
    }

    /**
     * Retrieves the authenticated user identifier from the request.
     *
     * <p>This method first attempts to obtain the principal from the servlet request.
     * If no principal is present, it falls back to the {@code X-Authenticated-User}
     * header, which is commonly used in UAA deployments. Returning {@code null}
     * indicates that the caller could not be authenticated.</p>
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if unavailable
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        if (principal != null && principal.getName() != null) {
            return principal.getName();
        }
        // Fallback to a custom header if the principal is not set
        String headerUser = request.getHeader("X-Authenticated-User");
        return (headerUser != null && !headerUser.isEmpty()) ? headerUser : null;
    }

    // other methods
}
